#!/bin/sh
'''exec' "$(dirname "$0")/python3" "$0" "$@"
' '''
# -*- coding: utf-8 -*-
import re
import sys
from {MODULE} import {ATTRIBUTE}
if __name__ == '__main__':
    sys.argv[0] = re.sub(r'(-script\.pyw|\.exe)?$', '', sys.argv[0])
    sys.exit({ATTRIBUTE}())

